"use client";

import * as React from "react";
import { Moon, Sun } from "lucide-react";

import { cn } from "@/lib/utils";

/**
 * Dark/light toggle for the moneytrees theme. The token sheet already ships
 * both palettes — `[data-theme="moneytrees"]` is the light base and `.dark`
 * overrides it — so toggling is just the `dark` class on <html>, persisted to
 * localStorage("mt-theme"). index.html applies the stored choice pre-paint
 * (inline script) so there's no flash; this component only reflects and
 * flips it. SSR renders the dark state (the shipped default) and corrects on
 * mount if the visitor chose light.
 */

const STORAGE_KEY = "mt-theme";

function currentIsDark(): boolean {
  if (typeof document === "undefined") return true;
  return document.documentElement.classList.contains("dark");
}

export function applyTheme(dark: boolean): void {
  document.documentElement.classList.toggle("dark", dark);
  try {
    localStorage.setItem(STORAGE_KEY, dark ? "dark" : "light");
  } catch {
    // storage can be unavailable (private mode); the class still applies
  }
  window.dispatchEvent(new CustomEvent("mt-theme-change", { detail: { dark } }));
}

/** Subscribe-to-DOM hook so every toggle instance stays in sync. */
export function useMoneytreesTheme(): [boolean, (dark: boolean) => void] {
  const [dark, setDark] = React.useState(true);
  React.useEffect(() => {
    setDark(currentIsDark());
    const onChange = (e: Event) => setDark((e as CustomEvent<{ dark: boolean }>).detail.dark);
    window.addEventListener("mt-theme-change", onChange);
    return () => window.removeEventListener("mt-theme-change", onChange);
  }, []);
  return [dark, applyTheme];
}

export function ThemeToggle({ className }: { className?: string }) {
  const [dark, setTheme] = useMoneytreesTheme();
  return (
    <button
      type="button"
      aria-label={dark ? "Switch to light mode" : "Switch to dark mode"}
      onClick={() => setTheme(!dark)}
      className={cn(
        "inline-flex size-9 items-center justify-center rounded-bubble-pill border border-border text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground",
        className,
      )}
    >
      {dark ? <Sun className="size-4" aria-hidden /> : <Moon className="size-4" aria-hidden />}
    </button>
  );
}
